// Скрипт печатает ход работы в stderr, а итог — последней строкой stdout: RESULT:{...}
const out = $input.first().json;
const lines = String(out.stdout || '').split(/\r?\n/).filter(Boolean);
const line = [...lines].reverse().find((l) => l.startsWith('RESULT:'));
if (!line) {
  throw new Error('Скрипт не вернул итог. Код выхода ' + out.exitCode + '. ' + String(out.stderr || '').slice(-600));
}
const r = JSON.parse(line.slice('RESULT:'.length));
if (!r.ok) throw new Error(r['ошибка'] || 'не удалось');
return [{ json: r }];

const r = $('Разобрать итог').first().json;
return [{ json: { kind: r['не_получилось'] ? 'warning' : 'info',
  title: `Пересъёмка: готово ${r['переснято']}` + (r['не_получилось'] ? `, ошибок ${r['не_получилось']}` : ''),
  text: `в очереди осталось ${r['осталось_в_очереди']} · кадры в ${r['папка']}` } }];

const r = $('Разобрать итог').first().json;
const out = { в_очереди: r['в_очереди'], переснято: r['переснято'], не_получилось: r['не_получилось'],
  осталось_в_очереди: r['осталось_в_очереди'], папка_с_кадрами: r['папка'] };
if (r['подсказка']) out.подсказка = r['подсказка'];
if (r['готово'] && r['готово'].length) out.готово = r['готово'];
if (r['ошибки'] && r['ошибки'].length) out.ошибки = r['ошибки'];
return [{ json: out }];
